from math import *

class Diem:
    def __init__(self, x, y):
        self.x = x
        self.y = y

    def khoang_cach_tu_tam_o(self):
        return sqrt(self.x * self.x + self.y * self.y)

    def khoang_cach(self, other):
        dx = self.x - other.x
        dy = self.y - other.y
        return sqrt(dx * dx + dy * dy)

    def dich_chuyen(self, dx, dy):
        self.x += dx
        self.y += dy

    def __str__(self):
        return "(" + str(self.x) + ", " + str(self.y) + ")"
```

